function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function codeReference(title, input, output, explanation) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;padding:24px;background:#090d16;color:#e5e7eb;font:15px/1.55 system-ui,sans-serif}main{max-width:620px;margin:auto;padding:24px;border:1px solid #334155;border-radius:14px;background:#111827}.eyebrow{color:#a78bfa;font:700 11px monospace;letter-spacing:.12em}h1{font-size:22px}code{color:#a7f3d0;overflow-wrap:anywhere}.result{padding:10px 12px;border-radius:8px;background:#052e2b;color:#a7f3d0}</style></head><body><main><p class="eyebrow">REFERENCE EXAMPLE · NOT A PROGRAM RUN</p><h1>${escapeHtml(title)}</h1><p><strong>Input:</strong> <code>${escapeHtml(input)}</code></p><p class="result"><strong>Expected value:</strong> <code>${escapeHtml(output)}</code></p><p>${escapeHtml(explanation)}</p></main></body></html>`;
}

function makeCodeLesson(course, lesson) {
  return {
    course,
    title: lesson.title,
    description: lesson.description,
    learningObjective: lesson.objective,
    instructions: lesson.steps,
    workedExample: { input: lesson.input, output: lesson.output, explanation: lesson.explanation },
    hint: lesson.hint,
    explanation: lesson.explanation,
    contentStatus: 'authored',
    assessmentMode: 'source-rubric',
    timeLimit: lesson.timeLimit || 420,
    testCases: lesson.checks.map((description, index) => ({ id: index + 1, description })),
    expectedOutput: codeReference(lesson.title, lesson.input, lesson.output, lesson.explanation),
    expectedOutputHint: `Reference example only — input: ${lesson.input}; expected value: ${lesson.output}. Submitted code is not executed in this mode.`,
    starterCode: lesson.starterCode,
  };
}

function makeHtmlLesson(lesson) {
  return {
    title: lesson.title,
    description: lesson.description,
    learningObjective: lesson.objective,
    instructions: lesson.steps,
    workedExample: { ...lesson.example, explanation: lesson.explanation },
    hint: lesson.hint,
    explanation: lesson.explanation,
    contentStatus: 'authored',
    assessmentMode: 'source-rubric',
    timeLimit: lesson.timeLimit || 360,
    testCases: lesson.checks.map((description, index) => ({ id: index + 1, description })),
    expectedOutput: lesson.expectedOutput,
    expectedOutputHint: 'Visual reference only. HTML completion is reviewed against source requirements, not browser-executed tests.',
    starterCode: lesson.starterCode,
  };
}

function makeCssLesson(lesson) {
  return {
    title: lesson.title,
    description: lesson.description,
    learningObjective: lesson.objective,
    instructions: lesson.steps,
    workedExample: {
      input: 'The supplied lesson-card markup and starter stylesheet.',
      output: 'The reference preview shows the requested grid arrangement.',
      explanation: lesson.explanation,
    },
    hint: lesson.hint,
    explanation: lesson.explanation,
    contentStatus: 'authored',
    assessmentMode: 'source-rubric',
    timeLimit: lesson.timeLimit || 420,
    testCases: lesson.checks.map((description, index) => ({ id: index + 1, description })),
    htmlCode: lesson.html,
    starterCode: lesson.starterCode,
    expectedOutput: `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;padding:24px;background:#090d16;color:#e5e7eb;font:15px/1.5 system-ui,sans-serif}.grid{max-width:760px;margin:auto;padding:16px;background:#111827;border:1px solid #334155;border-radius:14px}.grid>*{padding:16px;background:#1e293b;border:1px solid #475569;border-radius:9px}.grid h2{margin:0 0 8px}.grid p{margin:0;color:#cbd5e1}${lesson.referenceCss}</style></head><body>${lesson.html}</body></html>`,
    expectedOutputHint: 'Visual reference only. The preview shows authored example styles; submitted CSS is reviewed against source requirements, not compiled by the server validator.',
  };
}

const htmlDocument = (title, content) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title></head><body><main>${content}</main></body></html>`;

